+  Assert.equal(tabInfo.mode.name, "mail3PaneTab", "tab should be a 3-pane tab");
+  Assert.equal(
+    tabmail.currentTabInfo,
+    tabInfo,
+    "tab should open in the foreground"
+  );
+  Assert.equal(
+    tabInfo.folder,
+    inboxFolder,
+    "tab should load the correct folder"
