+  // Open in a new background tab by pressing shift.
+
+  leftClickOn(plainFolder);
+  tabPromise = promiseTabOpenAndReady();
+  await rightClickAndActivate(plainFolder, "folderPaneContext-openNewTab", {
+    shiftKey: true,
+  });
+  tabInfo = await tabPromise;
